function blockIssueMovement(issue) {
  var blockingChecklist = issue.getFieldValue("Blocking Checklist");
  var allItemsDone = true;

  for (var i = 0; i < blockingChecklist.length; i++) {
    if (!blockingChecklist[i].done) {
      allItemsDone = false;
      break;
    }
  }

  if (!allItemsDone) {
    return false;
  }

  // Block the issue from moving to another column
