// Your other server configurations and routes go here
```

Replace `http://your-wordpress-site.com` with the actual URL of your WordPress site.

3. Update your fetch requests in Next.js components:

In your Next.js components, update any fetch requests that make requests to your WordPress site to include the `origin` header. For example:

```javascript
import { useRouter } from 'next/router';

const MyComponent = () => {
  const router = useRouter();

  const handleClick = async () => {
    const response = await fetch(`${router.basePath}/api/my-endpoint`, {
      headers: {
        origin: 'http://your-wordpress-site.com',
      },
    });

    // Handle the response
  };

  return (
    <div>
      <button onClick={handleClick}>Click me</button>
    </div>
  );
};

export default MyComponent;
```

After implementing these changes, the CORS error should be resolved, and your Next.js application should be able to communicate with your WordPress site without issues.

