function tense = identify_tense(sentence)
    % Regular expression pattern for present, past, and future tenses
    pattern = {'present': '(?i)(be|am|is|are|was|were)\b', 'past': '(?i)(be|am|is|are|was|were)\b(ed)$', 'future': '(?i)(will|shall)\b'};

