Here's a Go program that parses a struct in a Go source file and generates an Avro schema from it:

```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"

	"github.com/apache/avro/avro"
	"github.com/apache/avro/avro/data"
)

func main() {
	file := "example.go"
	structName := "MyStruct"
	outputFile := "struct.avsc"

	code, err := ioutil.ReadFile(file)
	if err != nil {
		fmt.Println("Error reading file:", err)
		return
	}

	re := regexp.MustCompile(`type (\w+) struct {`)
	matches := re.FindStringSubmatch(string(code))
	if len(matches) != 2 {
		fmt.Println("Error parsing file:", "Invalid struct definition")
		return
	}

	structType := matches[1]

	fields := []data.Field{}
	for _, field := range strings.Split(matches[2], " ") {
		fieldName := field[:len(field)-1]
		fieldType := field[len(field)-1:]

		fields = append(fields, data.Field{Name: fieldName, Type: fieldType})
	}

	schema := avro.NewSchema(structType, fields)
	err = ioutil.WriteFile(outputFile, schema.ToString(), 0644)
	if err != nil {
		fmt.Println("Error writing file:", err)
		return
	}

	fmt.Printf("Avro schema generated for %s\n", structName)
}
```

Replace `example.go` with the name of your Go source file and `MyStruct` with the name of the struct you want to convert. The program will generate an Avro schema file named `struct.avsc` in the same directory as the Go source file.

