To create a script for Unity that displays a visualizer in time with an audio file, follow these steps:

1. Import necessary assets:
   - Audio file (e.g., .wav, .mp3)
   - Visualizer object (e.g., a 2D or 3D game object with a mesh renderer)

2. Create a new C# script named "AudioVisualizer". Attach this script to the visualizer object.

3. Add the following code to the "AudioVisualizer" script:

```csharp
using UnityEngine;
using UnityEngine.Audio;

public class AudioVisualizer : MonoBehaviour
{
    public AudioSource audioSource;
    public float visualizerScale = 1f;

    private MeshFilter meshFilter;
    private Mesh mesh;

    void Start()
    {
        meshFilter = GetComponent<MeshFilter>();
        mesh = meshFilter.mesh;

        audioSource = GetComponent<AudioSource>();
        audioSource.clip = LoadAudioClip();
        audioSource.Play();
    }

    void Update()
    {
        float amplitude = Mathf.Abs(audioSource.volume);
        amplitude = Mathf.Clamp01(amplitude);

        Vector3 scale = transform.localScale;
        scale.x = amplitude * visualizerScale;
        scale.y = amplitude * visualizerScale;
        scale.z = amplitude * visualizerScale;

        transform.localScale = scale;
    }

    private AudioClip LoadAudioClip()
    {
        string audioFilePath = "Path/To/Your/Audio/File.wav"; // Replace with the path to your audio file
        return AudioClip.Load(audioFilePath);
    }
}
```

4. Replace "Path/To/Your/Audio/File.wav" with the actual path to your audio file.

5. Adjust the `visualizerScale` variable to control the size of the visualizer.

6. Run your Unity project and you should see the visualizer responding to the audio file.

