// app.ts
import { useState } from 'react';
import { Bar } from 'react-chartjs-2';

const App = () => {
  const [dataset, setDataset] = useState([
    { label: 'Dataset 1', data: [10, 20, 30] },
    { label: 'Dataset 2', data: [5, 15, 25] },
  ]);

  const handleAddDataset = () => {
    const newDataset = { label: `Dataset ${dataset.length + 1}`, data: [Math.random() * 100, Math.random() * 100, Math.random() * 100] };
    setDataset((prevDataset) => [...prevDataset, newDataset]);
  };

  return (
    <div>
      <button onClick={handleAddDataset}>Add Dataset</button>
      <Bar data={{ labels: dataset.map((d) => d.label), datasets: dataset.map((d) => ({ label: d.label, data: d.data, backgroundColor: ['rgba(255, 99, 132, 0.2)', 'rgba(54, 162, 235, 0.2)', 'rgba(255, 206, 86, 0.2)'] })) }} />
    </div>
  );
};

export default App;
```

