```powershell
# Define the function to check if an SID occurs only in the SIDHistory
function CheckSidInSidHistory($sid) {
    $domain = (Get-ADDomain).Name
    $searchBase = "DC=$domain,DC=local"
    $filter = "(&(objectClass=user)(sAMAccountName=*$sid*))"

    $results = Get-ADObject -Filter $filter -SearchBase $searchBase -Properties sAMAccountName, memberOf

    foreach ($result in $results) {
        if ($result.memberOf -ne $null) {
            $members = $result.memberOf | ForEach-Object { $_.GetDirectoryEntry().Path }
            if ($members -contains "CN=SID History,$domain") {
                return $true
            }
        }
    }

    return $false
}

# Define the function to recursively check folders for ACLs with SIDs in SIDHistory
function CheckFoldersForSidHistory($folderPath) {
    Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
        $acl = Get-Acl -Path $_.FullName
        $sidHistorySids = $acl.Access | Where-Object {$_.IdentityReference -match '^S-1-5-21-'} | ForEach-Object {$_.IdentityReference}

        if ($sidHistorySids -ne $null) {
            foreach ($sid in $sidHistorySids) {
                if (CheckSidInSidHistory($sid)) {
                    Write-Host "Folder: $($_.FullName)"
                    Write-Host "ACL: $($acl.ToString())"
                    Write-Host "SID: $sid"
                    Write-Host "SID History: True"
                    Write-Host "--------------------"
                }
            }
        }

        CheckFoldersForSidHistory($_.FullName)
    }
}

# Call the function with the root folder path
CheckFoldersForSidHistory("C:\")
```
